    import csv as _csv, os as _os, collections as _col
    _els = list(_csv.DictReader(open(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '..', 'plan', '04-architecture', 'elements.csv'), encoding='utf-8')))
    _where = _col.OrderedDict()
    for x in _els: _where.setdefault(x['where'], _col.OrderedDict()).setdefault(x['standard_group'], []).append(x)
    def _elblock(where, groups):
        n = sum(len(v) for v in groups.values()); out = '<h3>%s <span>%d elements</span></h3>' % (where, n)
        for g, items in groups.items(): out += '<p class="el-group">%s</p><ul class="el-list">%s</ul>' % (g, ''.join('<li>%s <i>%s</i></li>' % (i['element'], i['equation_term']) for i in items))
        return T(out, 'rs-els glass rv', mb=0)
